import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';

test('exportCsv returns string with header line', () => {
  const result = exportCsv([]);

  assert(typeof result === 'string');
  assert(result.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n'));
});

test('exportCsv exports single invoice', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);
  const lines = result.split('\n');

  assert.equal(lines.length, 3);
  assert(lines[0].startsWith('number,customer,issueDate,dueDate,status'));
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[1].includes('Northwind Studio'));
  assert.equal(lines[2], '');
});

test('exportCsv includes customer name', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-003',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);

  assert(result.includes('Kite & Co'));
});

test('exportCsv formats amounts as euros with 2 decimals and dot', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);

  assert(result.includes('950.00'));
  assert(result.includes('1149.50') || result.includes('1199.50'));
});

test('exportCsv does not include currency signs or thousands separators', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 100,
          unitPrice: 10000,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);

  assert(!result.includes('€'));
  assert(!result.includes(','));
});

test('exportCsv escapes fields with commas', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-006',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);

  assert(result.includes('"Marlow "The Print Shop""'));
});

test('exportCsv escapes fields with double quotes', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-006',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);

  assert(result.includes('"Marlow "The Print Shop""'));
});

test('exportCsv exports multiple invoices in order', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-002',
      issueDate: '2026-10-10',
      dueDate: '2026-11-09',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);
  const lines = result.split('\n');

  assert.equal(lines.length, 4);
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[2].includes('INV-2026-0002'));
});

test('exportCsv includes all columns', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 10,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);
  const lines = result.split('\n');
  const headerCols = lines[0].split(',');
  const dataCols = lines[1].split(',');

  assert.equal(headerCols.length, 10);
  assert.equal(dataCols.length, 10);
});

test('exportCsv includes correct columns in order', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);
  const lines = result.split('\n');

  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv with discount and VAT', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 100,
          unitPrice: 10000,
          vatRate: 21,
          discountPercent: 10,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);

  assert(result.includes('1000000'));
  assert(result.includes('100000'));
  assert(result.includes('900000'));
});

test('exportCsv with payment reduces due', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'partially_paid',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
      payments: [{ amount: 50000, date: '2026-10-15' }],
    },
  ];

  const result = exportCsv(invoices);

  assert(result.includes('64950') || result.includes('64.95'));
});

test('exportCsv ends with newline', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 1,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 0,
        },
      ],
    },
  ];

  const result = exportCsv(invoices);

  assert(result.endsWith('\n'));
});

test('exportCsv with empty invoices array', () => {
  const result = exportCsv([]);

  assert.equal(result, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

